/**
 * PredictionPanel - Flow & Positioning directional read for one contract.
 * Fetches lazily (only while the card is expanded) and supports a manual refresh.
 * - Portions generated by AI
 */

import { useState } from 'react';
import {
  TrendingUp,
  TrendingDown,
  Minus,
  RefreshCw,
  Activity,
  ChevronDown,
  ChevronUp,
} from 'lucide-react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import apiClient from '@/api/client';
import type { DirectionPrediction } from '@/types';
import { formatMarketTimeShort } from '@/utils/marketTime';

interface PredictionPanelProps {
  symbol: string;
  expiry?: string;
  strike?: number;
  spot?: number;
  expanded: boolean;
}

function directionColor(direction: string): string {
  if (direction === 'BULLISH') return 'text-green-400';
  if (direction === 'BEARISH') return 'text-red-400';
  return 'text-yellow-400';
}

function directionIcon(direction: string) {
  if (direction === 'BULLISH') return <TrendingUp className="text-green-400" size={18} />;
  if (direction === 'BEARISH') return <TrendingDown className="text-red-400" size={18} />;
  return <Minus className="text-yellow-400" size={18} />;
}

function barColor(direction: string): string {
  if (direction === 'BULLISH') return 'bg-green-500';
  if (direction === 'BEARISH') return 'bg-red-500';
  return 'bg-yellow-500';
}

/** Signed factor bar: fills left of centre for bearish, right for bullish. */
function SignalBar({ score }: { score: number | null }) {
  if (score === null) {
    return <div className="h-1.5 rounded-full bg-dark-700" />;
  }
  const magnitude = Math.min(Math.abs(score), 1) * 50;
  const bullish = score >= 0;
  return (
    <div className="relative h-1.5 rounded-full bg-dark-700 overflow-hidden">
      <div className="absolute inset-y-0 left-1/2 w-px bg-white/20" />
      <div
        className={`absolute inset-y-0 ${bullish ? 'bg-green-500/70' : 'bg-red-500/70'}`}
        style={
          bullish
            ? { left: '50%', width: `${magnitude}%` }
            : { right: '50%', width: `${magnitude}%` }
        }
      />
    </div>
  );
}

export function PredictionPanel({ symbol, expiry, strike, spot, expanded }: PredictionPanelProps) {
  const queryClient = useQueryClient();
  const [showFactors, setShowFactors] = useState(false);
  const queryKey = ['prediction', symbol, expiry ?? null, strike ?? null];

  const { data, isLoading, isError, error, refetch } = useQuery({
    queryKey,
    queryFn: () => apiClient.getPrediction(symbol, { expiry, strike, spot }),
    enabled: expanded && !!symbol,
    staleTime: 15 * 60 * 1000,
    refetchOnWindowFocus: false,
  });

  // refetch() replays the original query, so a forced refresh needs its own
  // call that writes the result back into the cache.
  const refresh = useMutation({
    mutationFn: () => apiClient.getPrediction(symbol, { expiry, strike, spot }, true),
    onSuccess: (fresh: DirectionPrediction) => queryClient.setQueryData(queryKey, fresh),
  });

  const status = (error as any)?.response?.status;
  const busy = isLoading || refresh.isPending;

  return (
    <div className="mt-3 pt-3 border-t border-white/5">
      <div className="flex items-center justify-between mb-2">
        <div className="flex items-center gap-1.5 text-xs font-semibold text-gray-400 uppercase tracking-wide">
          <Activity size={13} className="text-primary-400" />
          Flow &amp; Positioning
        </div>
        {data && (
          <button
            onClick={() => refresh.mutate()}
            disabled={busy}
            className="p-1 hover:bg-white/10 rounded transition-colors"
            title="Refresh prediction"
          >
            <RefreshCw size={13} className={`text-gray-500 ${refresh.isPending ? 'animate-spin' : ''}`} />
          </button>
        )}
      </div>

      {isLoading && (
        <div className="flex items-center gap-2 text-sm text-gray-500 py-2">
          <div className="w-3.5 h-3.5 border-2 border-gray-600 border-t-primary-500 rounded-full animate-spin" />
          Reading options flow...
        </div>
      )}

      {isError && (
        <div className="text-sm text-gray-500 py-1">
          {status === 503
            ? 'Unusual Whales is not configured.'
            : status === 404
            ? 'No positioning data for this ticker.'
            : (
              <>
                Unable to load prediction.{' '}
                <button onClick={() => refetch()} className="text-primary-400 hover:underline">
                  Retry
                </button>
              </>
            )}
        </div>
      )}

      {data && (
        <>
          <div className="flex items-center justify-between mb-2">
            <div className="flex items-center gap-2">
              {directionIcon(data.direction)}
              <span className={`text-base font-bold ${directionColor(data.direction)}`}>
                {data.direction}
              </span>
              <span className="text-xs text-gray-500">
                {data.score > 0 ? '+' : ''}
                {data.score.toFixed(0)}
              </span>
            </div>
            <div className="text-right">
              <div className="text-[10px] text-gray-500 uppercase">Confidence</div>
              <div className="text-sm font-semibold text-white">
                {Math.round(data.confidence * 100)}%
              </div>
            </div>
          </div>

          <div className="w-full bg-dark-700 rounded-full h-1.5 mb-2">
            <div
              className={`h-1.5 rounded-full ${barColor(data.direction)}`}
              style={{ width: `${Math.round(data.confidence * 100)}%` }}
            />
          </div>

          <p className="text-xs text-gray-400 leading-relaxed">{data.put_seller_note}</p>

          <button
            onClick={() => setShowFactors(!showFactors)}
            className="w-full mt-2 flex items-center justify-center gap-1 text-[11px] text-gray-500 hover:text-gray-300 transition-colors"
          >
            {showFactors ? (
              <>Hide factors <ChevronUp size={12} /></>
            ) : (
              <>{data.signals.filter((s) => s.available).length} of {data.signals.length} factors <ChevronDown size={12} /></>
            )}
          </button>

          {showFactors && (
            <div className="mt-2 space-y-2">
              {data.signals.map((signal) => (
                <div key={signal.key} className={signal.available ? '' : 'opacity-40'}>
                  <div className="flex items-baseline justify-between gap-2 text-xs">
                    <span className="text-gray-300">{signal.label}</span>
                    <span className="text-gray-500 tabular-nums">
                      {Math.round(signal.weight * 100)}%
                    </span>
                  </div>
                  <div className="my-1">
                    <SignalBar score={signal.score} />
                  </div>
                  <p className="text-[11px] text-gray-500 leading-snug">{signal.detail}</p>
                </div>
              ))}
              <p className="text-[10px] text-gray-600 pt-1 leading-snug">{data.disclaimer}</p>
            </div>
          )}

          <div className="mt-2 text-[10px] text-gray-600">
            {data.cached_at
              ? `Cached ${formatMarketTimeShort(data.cached_at)}`
              : `Updated ${formatMarketTimeShort(data.as_of)}`}
          </div>
        </>
      )}
    </div>
  );
}
